#[cfg(test)]
mod tests {
    use super::TLT;

    #[test]
    fn single_corner_masks_match_verified_convention() {
        // Empirically verified against the Python original on a rendered
        // sphere: single-corner masks must cut exactly the three edges
        // incident to that corner (CUBE_EDGES order).
        let expected: [&[&[u8]]; 8] = [
            &[&[0, 1, 2]],   // bit 0 -> corner 0
            &[&[2, 10, 11]], // bit 1 -> corner 4 (z edge)
            &[&[1, 8, 9]],   // bit 2 -> corner 2 (y edge)
            &[&[3, 10, 9]],  // bit 3 -> corner 6 (y+z)
            &[&[0, 6, 7]],   // bit 4 -> corner 1 (x edge)
            &[&[6, 11, 4]],  // bit 5 -> corner 5 (x+z)
            &[&[5, 8, 7]],   // bit 6 -> corner 3 (x+y)
            &[&[3, 5, 4]],   // bit 7 -> corner 7 (x+y+z)
        ];
        for (bit, exp) in expected.iter().enumerate() {
            assert_eq!(TLT[1 << bit], *exp, "mask bit {}", bit);
        }
    }

    #[test]
    fn uniform_masks_are_sentinels() {
        assert_eq!(TLT[0], &[&[0]]);
        assert_eq!(TLT[255], &[&[0]]);
    }

    #[test]
    fn all_edge_indices_in_range() {
        for (mask, polys) in TLT.iter().enumerate() {
            for poly in polys.iter() {
                assert!(!poly.is_empty(), "mask {mask}: empty polygon");
                for &e in poly.iter() {
                    assert!(e < 12, "mask {mask}: edge index {e}");
                }
            }
        }
    }
}
